import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../utils/api';

export default function LoginPage() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault(); setError(''); setLoading(true);
    try {
      const res = await api.post('/auth/login', form);
      login(res.data.user, res.data.token);
      const role = res.data.user.role;
      if (role === 'admin')      navigate('/admin');
      else if (role === 'restaurant') navigate('/restaurant');
      else if (role === 'delivery')   navigate('/delivery');
      else navigate('/home');
    } catch (err) { setError(err.response?.data?.message || 'Login failed'); }
    finally { setLoading(false); }
  };

  const quickLogin = (email, password) => setForm({ email, password });

  return (
    <div className="auth-page">
      <div className="auth-card" style={{ maxWidth: 460 }}>
        <div className="auth-logo">
          <div className="emoji">🦜</div>
          <h2>Welcome to <span>Parrot</span></h2>
          <p>Feast Your Senses, Fast and Fresh</p>
        </div>
        {error && <div className="error-msg">⚠️ {error}</div>}
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Email Address</label>
            <input type="email" placeholder="youremail@gmail.com" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} required />
          </div>
          <div className="form-group">
            <label>Password</label>
            <input type="password" placeholder="Enter your password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} required />
          </div>
          <button type="submit" className="btn-primary" style={{ width: '100%' }} disabled={loading}>
            {loading ? '⏳ Signing In...' : 'Login'}
          </button>
        </form>
        <div className="auth-switch">
          Don't have an account? <Link to="/register" style={{ color: 'var(--orange)', fontWeight: 600 }}>Sign Up</Link>
        </div>

        {/* Demo credentials */}
        <div style={{ marginTop: 20, background: '#f8f9fa', borderRadius: 12, padding: 16 }}>
          <p style={{ fontSize: 12, fontWeight: 700, color: '#555', marginBottom: 10 }}>⚡ Quick Login (click to fill):</p>
          {[
            { label: '👤 Customer',   email: 'user@parrot.com',       pw: 'user123',  color: '#3498db' },
            { label: '👑 Admin',      email: 'admin@parrot.com',      pw: 'admin123', color: '#e74c3c' },
            { label: "🏪 McDonald's", email: 'mcdonalds@parrot.com',  pw: 'rest123',  color: '#9b59b6' },
            { label: '🏍️ Delivery',   email: 'ravi@parrot.com',       pw: 'del123',   color: '#27ae60' },
          ].map(c => (
            <div key={c.email} onClick={() => quickLogin(c.email, c.pw)}
              style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '8px 12px', marginBottom: 6, borderRadius: 8, background: 'white', cursor: 'pointer', border: `1px solid ${c.color}20`, transition: 'background .2s' }}
              onMouseEnter={e => e.currentTarget.style.background = c.color + '12'}
              onMouseLeave={e => e.currentTarget.style.background = 'white'}
            >
              <span style={{ fontSize: 13, fontWeight: 600, color: c.color }}>{c.label}</span>
              <span style={{ fontSize: 11, color: '#999', fontFamily: 'monospace' }}>{c.email}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
